import styled from '@emotion/styled';
import { theme } from 'theme';

import type { Position3 } from '../../../../types';
import type { TieScenario } from '../../../../utils/tiesDetection';

interface PositionProps {
  $position?: Position3;
}

interface TieProps {
  $tieScenario?: TieScenario;
  $dataIndex?: 0 | 1 | 2;
}

const positionOrderStyles: Record<Position3, { order: string }> = {
  '1': { order: '1' },
  '2': { order: '2' },
  '3': { order: '3' },
};

const positionContainerStyles: Record<
  Position3,
  { borderRadius: string; paddingBottom: string }
> = {
  '1': { borderRadius: '8px', paddingBottom: '41.56%' },
  '2': { borderRadius: '4px', paddingBottom: '23.38%' },
  '3': { borderRadius: '4px', paddingBottom: '18.83%' },
};

const positionTextStyles: Record<Position3, { fontSize: string }> = {
  '1': { fontSize: '20px' },
  '2': { fontSize: '16px' },
  '3': { fontSize: '16px' },
};

const tiePaddingByScenario: Record<
  Exclude<TieScenario, 'no-tie'>,
  [string, string, string]
> = {
  '1st-tie-simple': ['32.5%', '32.5%', '18.83%'],
  '1st-tie-triple': ['28%', '28%', '28%'],
  '2nd-tie': ['41.56%', '21.1%', '21.1%'],
};

const resolveContainerPaddingBottom = ({
  $position,
  $tieScenario,
  $dataIndex,
}: PositionProps & TieProps): string | undefined => {
  if ($tieScenario && $tieScenario !== 'no-tie' && $dataIndex !== undefined) {
    return tiePaddingByScenario[$tieScenario][$dataIndex];
  }

  return $position != null
    ? positionContainerStyles[$position].paddingBottom
    : undefined;
};

export const StyledCupWinnersBox = styled.div({
  display: 'flex',
  flexWrap: 'wrap',
  alignItems: 'flex-start',
  justifyContent: 'center',
  gap: '8px',
});

export const StyledCupWinnerItem = styled.div<PositionProps & TieProps>(
  ({ $position }) => ({
    position: 'relative',
    width: '100%',
    ...($position != null ? positionOrderStyles[$position] : {}),
  }),
);

export const StyledCupWinnerItemContainer = styled.div<
  PositionProps & TieProps
>((props) => {
  const { $position } = props;
  const paddingBottom = resolveContainerPaddingBottom(props);

  return {
    position: 'relative',
    overflow: 'hidden',
    ...($position != null
      ? {
          borderRadius: positionContainerStyles[$position].borderRadius,
        }
      : {}),
    ...(paddingBottom != null ? { paddingBottom } : {}),
  };
});

export const StyledImage = styled.img({
  width: '100%',
  height: '100%',
  objectFit: 'cover',
  position: 'absolute',
});

export const StyledCupWinnerBoxContent = styled.div({
  width: '100%',
  height: '100%',
  padding: '8px',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'end',
  alignItems: 'start',
  gap: '4px',
  objectFit: 'cover',
  position: 'absolute',
  background:
    'linear-gradient(0deg, rgba(23, 23, 23, 0.24), rgba(23, 23, 23, 0.24)), linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.88) 100%)',
});

export const StyledCupWinnerCountryFlag = styled.span({
  color: '#fff',
  fontFamily: theme.fonts.heading,
  fontSize: '12px',
  lineHeight: '16px',
  fontWeight: '600',
  padding: '2px 4px',
  background: '#FFFFFF3D',
  borderRadius: '100px',
});

export const StyledCupWinnerText = styled.div<PositionProps>(
  ({ $position }) => ({
    color: '#fff',
    fontFamily: theme.fonts.heading,
    ...($position != null ? positionTextStyles[$position] : {}),
  }),
);

export const StyledCupWinnerTitle = styled.div({
  width: '100%',
  fontFamily: theme.fonts.heading,
  fontSize: '16px',
  fontWeight: '600',
  lineHeight: '24px',
  color: 'rgba(20, 20, 20, 0.56)',
});
